-- مولَّد تلقائياً بواسطة scripts/basira-caller-build-data.cjs — لا تعدّله يدوياً.
-- يُطبَّق بعد schema.sql ثم seed-schema.sql. آمن لإعادة التشغيل.
begin;
on conflict (e164) do update set display_name = excluded.display_name, category = excluded.category, verified = true, name_source = 'verified',
  source_name = excluded.source_name, source_url = excluded.source_url, updated_at = now() where not public.bc_numbers.hidden;
update public.bc_numbers set official_reports = 0, official_subject = null where official_reports > 0;
on conflict (e164) do update set official_reports = excluded.official_reports, official_subject = excluded.official_subject, official_last = excluded.official_last,
  category = case when public.bc_numbers.verified then public.bc_numbers.category else excluded.category end,
  source_name = coalesce(public.bc_numbers.source_name, excluded.source_name), source_url = coalesce(public.bc_numbers.source_url, excluded.source_url);
on conflict (e164) do update set official_reports = excluded.official_reports, official_subject = excluded.official_subject, official_last = excluded.official_last,
  category = case when public.bc_numbers.verified then public.bc_numbers.category else excluded.category end,
  source_name = coalesce(public.bc_numbers.source_name, excluded.source_name), source_url = coalesce(public.bc_numbers.source_url, excluded.source_url);
commit;
